<script>
    // Data siswa dummy, bisa diganti dengan hasil fetch backend
    const siswaData = [
        {
            nama: "Lucian",
            jurusan: "TKJ",
            bulan: "Januari",
            tahun: "2025",
            hadir: 26,
            tidakHadir: 5,
            izinSakit: 3,
            terlambat: 3,
            detail: [
                { tanggal: "02-01-2025", keterangan: "Tidak Hadir" },
                { tanggal: "03-01-2025", keterangan: "Sakit" },
                { tanggal: "06-01-2025", keterangan: "Izin" },
                { tanggal: "10-01-2025", keterangan: "Tidak Hadir" },
                { tanggal: "11-01-2025", keterangan: "Sakit" },
                { tanggal: "15-01-2025", keterangan: "Tidak Hadir" },
                { tanggal: "20-01-2025", keterangan: "Tidak Hadir" },
                { tanggal: "04-01-2025", keterangan: "Terlambat" },
                { tanggal: "07-01-2025", keterangan: "Terlambat" },
                { tanggal: "17-01-2025", keterangan: "Terlambat" }
            ]
        },
        {
            nama: "Rina",
            jurusan: "RPL",
            bulan: "Januari",
            tahun: "2025",
            hadir: 28,
            tidakHadir: 0,
            izinSakit: 1,
            terlambat: 0,
            detail: [
                { tanggal: "03-01-2025", keterangan: "Sakit" }
            ]
        },
        {
            nama: "Budi",
            jurusan: "TKJ",
            bulan: "Februari",
            tahun: "2025",
            hadir: 23,
            tidakHadir: 2,
            izinSakit: 0,
            terlambat: 0,
            detail: [
                { tanggal: "10-02-2025", keterangan: "Tidak Hadir" },
                { tanggal: "11-02-2025", keterangan: "Tidak Hadir" }
            ]
        }
    ];

    // State untuk filter
    let selectedJurusan = null;
    let selectedBulan = null;
    let selectedTahun = null;

    // Render function
    function renderAttendanceList() {
        const list = document.getElementById("attendanceList");
        list.innerHTML = '';
        // Filter data
        const filtered = siswaData.filter(s => 
            (!selectedJurusan || s.jurusan === selectedJurusan)
            && (!selectedBulan || s.bulan === selectedBulan)
            && (!selectedTahun || s.tahun === selectedTahun)
        );
        if(filtered.length === 0){
            list.innerHTML = `<div class="alert alert-warning">Data tidak ditemukan.</div>`;
            return;
        }
        filtered.forEach(s => {
            // Group detail kiri-kanan (2 kolom)
            let detailKiri = "", detailKanan = "";
            s.detail.forEach((d, i) => {
                const html = `<p>${d.tanggal} : ${d.keterangan}</p>`;
                if(i % 2 === 0) detailKiri += html;
                else detailKanan += html;
            });
            list.innerHTML += `
            <div class="attendance-card card p-3 mb-3" onclick="toggleDetails(this)">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>${s.nama} - ${s.jurusan}</h5>
                    <i class="bi bi-chevron-down"></i>
                </div>
                <div class="attendance-summary">
                    <p><strong>Hadir:</strong> ${s.hadir} hari</p>
                    <p><strong>Tidak Hadir:</strong> ${s.tidakHadir} hari</p>
                    <p><strong>Izin/Sakit:</strong> ${s.izinSakit} hari</p>
                    <p><strong>Terlambat:</strong> ${s.terlambat} hari</p>
                </div>
                <div class="details" style="display: none;">
                    <p class="fw-bold">Detail Ketidakhadiran:</p>
                    <div class="row">
                        <div class="col-md-6">${detailKiri}</div>
                        <div class="col-md-6">${detailKanan}</div>
                    </div>
                </div>
            </div>`;
        });
    }

    // Handle dropdown
    function setupDropdown(id, setSelected, setBtnText) {
        document.querySelectorAll(`#${id} .dropdown-item`).forEach(item => {
            item.addEventListener('click', function(e){
                e.preventDefault();
                setSelected(this.textContent);
                setBtnText(this.textContent);
                renderAttendanceList();
            });
        });
    }

    document.addEventListener("DOMContentLoaded", function () {
        // Setup jurusan dropdown
        setupDropdown("jurusanDropdown", val => selectedJurusan = val, txt => document.getElementById('jurusanDropdownBtn').textContent = txt);
        setupDropdown("bulanDropdown", val => selectedBulan = val, txt => document.getElementById('bulanDropdownBtn').textContent = txt);
        setupDropdown("tahunDropdown", val => selectedTahun = val, txt => document.getElementById('tahunDropdownBtn').textContent = txt);
        renderAttendanceList();
    });

    // Toggle details
    function toggleDetails(element) {
        var details = element.querySelector('.details');
        var chevron = element.querySelector('.bi-chevron-down, .bi-chevron-up');
        if (details.style.display === 'none' || details.style.display === '') {
            details.style.display = 'block';
            chevron.classList.remove('bi-chevron-down');
            chevron.classList.add('bi-chevron-up');
        } else {
            details.style.display = 'none';
            chevron.classList.remove('bi-chevron-up');
            chevron.classList.add('bi-chevron-down');
        }
    }
</script>
